values
  ('00000000-0000-4000-8000-000000000001', 10, '/img/hero.webp', false, 'A Legacy Care caregiver in a blue polo sitting beside a smiling older woman on her living-room couch, holding her hands', '', 'Legacy Care', true, 1343, 680, 'image/webp'),
  ('00000000-0000-4000-8000-000000000002', 20, '/img/meal.webp', false, 'A caregiver handing a plate of fresh food to a smiling older woman at her kitchen table', '', 'Legacy Care', false, 809, 699, 'image/webp'),
  ('00000000-0000-4000-8000-000000000003', 30, '/img/hands.webp', false, 'A younger pair of hands gently holding an older pair of hands', '', 'Legacy Care', false, 685, 621, 'image/webp'),
  ('00000000-0000-4000-8000-000000000004', 40, '/img/walk.webp', false, 'A caregiver walking arm in arm with an older woman using a cane along a garden path', '', 'Legacy Care', false, 850, 657, 'image/webp'),
  ('00000000-0000-4000-8000-000000000005', 50, '/img/hero.webp', false, '', '', 'Legacy Care', false, 1343, 680, 'image/webp'),
  ('00000000-0000-4000-8000-000000000006', 60, '/img/logo.webp', false, 'Legacy Care LLC. Compassion. Dignity. Legacy.', '', 'Legacy Care', false, 805, 1054, 'image/webp')
on conflict (id) do nothing;

-- First editor: the HAND operator inbox, so the site can be tested before the
-- client's own email is added (admin Editors tab or LEGACY_CARE_LLC_OWNER_EMAILS).
insert into command.legacy_care_llc_editors (email, role)
values ('hand@handprotocol.org', 'owner')
on conflict do nothing;
